def semver_sort(versions):
    def parse_key(v):
        main_build = v.split('+', 1)[0]
        if '-' in main_build:
            core, pre = main_build.split('-', 1)
        else:
            core, pre = main_build, None

        parts = core.split('.')
        major, minor, patch = (int(p) for p in parts[:3])

        if pre is None:
            has_no_prerelease = 1
            pre_key = ()
        else:
            has_no_prerelease = 0
            idents = pre.split('.')
            pre_key = tuple(
                (0, int(ident)) if ident.isdigit() else (1, ident)
                for ident in idents
            )

        return (major, minor, patch, has_no_prerelease, pre_key)

    indexed = list(enumerate(versions))
    indexed.sort(key=lambda pair: (parse_key(pair[1]), pair[0]))
    return [v for _, v in indexed]

